create table if not exists public.platform_default_assets(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('logo','banner','service')),asset_key text not null,category text,image_url text not null,active boolean not null default true,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id),unique(kind,asset_key));
alter table public.platform_default_assets enable row level security;
drop policy if exists platform_default_assets_read on public.platform_default_assets; create policy platform_default_assets_read on public.platform_default_assets for select to anon,authenticated using(active=true or public.is_platform_admin());
drop policy if exists platform_default_assets_admin_write on public.platform_default_assets; create policy platform_default_assets_admin_write on public.platform_default_assets for all to authenticated using(public.is_platform_admin()) with check(public.is_platform_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('platform-default-media','platform-default-media',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists platform_default_media_public_read on storage.objects; create policy platform_default_media_public_read on storage.objects for select to public using(bucket_id='platform-default-media');
drop policy if exists platform_default_media_admin_insert on storage.objects; create policy platform_default_media_admin_insert on storage.objects for insert to authenticated with check(bucket_id='platform-default-media' and public.is_platform_admin());
drop policy if exists platform_default_media_admin_update on storage.objects; create policy platform_default_media_admin_update on storage.objects for update to authenticated using(bucket_id='platform-default-media' and public.is_platform_admin()) with check(bucket_id='platform-default-media' and public.is_platform_admin());
drop policy if exists platform_default_media_admin_delete on storage.objects; create policy platform_default_media_admin_delete on storage.objects for delete to authenticated using(bucket_id='platform-default-media' and public.is_platform_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('business-public-media','business-public-media',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists business_public_media_read on storage.objects; create policy business_public_media_read on storage.objects for select to public using(bucket_id='business-public-media');
drop policy if exists business_public_media_member_insert on storage.objects; create policy business_public_media_member_insert on storage.objects for insert to authenticated with check(bucket_id='business-public-media' and exists(select 1 from public.business_members bm where bm.user_id=auth.uid() and bm.business_id::text=(storage.foldername(name))[1]));
drop policy if exists business_public_media_member_update on storage.objects; create policy business_public_media_member_update on storage.objects for update to authenticated using(bucket_id='business-public-media' and exists(select 1 from public.business_members bm where bm.user_id=auth.uid() and bm.business_id::text=(storage.foldername(name))[1])) with check(bucket_id='business-public-media' and exists(select 1 from public.business_members bm where bm.user_id=auth.uid() and bm.business_id::text=(storage.foldername(name))[1]));
drop policy if exists business_public_media_member_delete on storage.objects; create policy business_public_media_member_delete on storage.objects for delete to authenticated using(bucket_id='business-public-media' and exists(select 1 from public.business_members bm where bm.user_id=auth.uid() and bm.business_id::text=(storage.foldername(name))[1]));
